// The lesson list the app walks. Consonants first: the lock chain in
// LessonMap/TraceView is "the letter before this one is cleared", by *index*,
// so putting the vowels in front would re-lock every consonant a child has
// already earned. Teaching order says vowels first — that swap is this one
// line, plus a decision about what it does to progress already on the device.
export const CURRICULUM = [...CONSONANTS, ...VOWELS];
